package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"  // PIC X len=1 = "N"
var WsLeapFlag string = "N" // PIC X len=1 = "N"
var WsQ int64 = 0           // PIC 9(4) len=4 = 0
var WsR4 int64 = 0          // PIC 9(3) len=3 = 0
var WsR100 int64 = 0        // PIC 9(3) len=3 = 0
var WsR400 int64 = 0        // PIC 9(3) len=3 = 0
var WsMaxDay int64 = 0      // PIC 99 len=2 = 0
var WsValid int64 = 0       // PIC 99 len=2 = 0
var WsBadMonth int64 = 0    // PIC 99 len=2 = 0
var WsBadDay int64 = 0      // PIC 99 len=2 = 0

var curRec DateRec
var dateFile *os.File
var dateReader *bufio.Reader

func format9(v int64, width int) string {
	mod := int64(1)
	for i := 0; i < width; i++ {
		mod *= 10
	}
	if mod != 0 {
		v = v % mod
		if v < 0 {
			v = -v
		}
	}
	s := strconv.FormatInt(v, 10)
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	} else if len(s) > width {
		s = s[len(s)-width:]
	}
	return s
}

func parseNum(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	v, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return 0
	}
	return v
}

func padTrunc(s string, n int) string {
	if len(s) < n {
		return s + strings.Repeat(" ", n-len(s))
	}
	if len(s) > n {
		return s[:n]
	}
	return s
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	dateFile = f
	dateReader = bufio.NewReader(dateFile)
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	if err := dateFile.Close(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	fmt.Print("VALID: " + format9(WsValid, 2) + " BAD MONTH: " + format9(WsBadMonth, 2) + " BAD DAY: " + format9(WsBadDay, 2) + "\n")
}

func ReadPara() {
	line, err := dateReader.ReadString('\n')
	if err != nil {
		if err == io.EOF {
			if len(line) == 0 {
				WsEofFlag = "Y"
				return
			}
			// last line without newline: fall through to process line
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
	// strip single line terminator (LF and optional CR)
	if strings.HasSuffix(line, "\n") {
		line = line[:len(line)-1]
		if strings.HasSuffix(line, "\r") {
			line = line[:len(line)-1]
		}
	} else if strings.HasSuffix(line, "\r") {
		line = line[:len(line)-1]
	}
	line = padTrunc(line, 12)
	curRec.DtId = line[0:4]
	curRec.DtYyyy = parseNum(line[4:8])
	curRec.DtMm = parseNum(line[8:10])
	curRec.DtDd = parseNum(line[10:12])
}

func ProcessPara() {
	LeapPara()
	if curRec.DtMm < 1 || curRec.DtMm > 12 {
		WsBadMonth = (WsBadMonth + 1) % 100
		fmt.Print(curRec.DtId + " BAD MONTH " + format9(curRec.DtMm, 2) + "\n")
	} else {
		DaysPara()
		if curRec.DtDd < 1 || curRec.DtDd > WsMaxDay {
			WsBadDay = (WsBadDay + 1) % 100
			fmt.Print(curRec.DtId + " BAD DAY " + format9(curRec.DtDd, 2) + " MAX " + format9(WsMaxDay, 2) + "\n")
		} else {
			WsValid = (WsValid + 1) % 100
			fmt.Print(curRec.DtId + " VALID " + format9(curRec.DtYyyy, 4) + "-" + format9(curRec.DtMm, 2) + "-" + format9(curRec.DtDd, 2) + "\n")
		}
	}
	ReadPara()
}

func LeapPara() {
	WsQ = curRec.DtYyyy / 4
	WsR4 = curRec.DtYyyy % 4
	WsQ = curRec.DtYyyy / 100
	WsR100 = curRec.DtYyyy % 100
	WsQ = curRec.DtYyyy / 400
	WsR400 = curRec.DtYyyy % 400
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DaysPara() {
	switch curRec.DtMm {
	case 2:
		if WsLeapFlag == "Y" {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
}

func main() {
	MainPara()
}
